import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { test, expect } from '@playwright/test';

// The page under test is generated by the C# tool tools/ExportCredentialPage
// (see README.md). The generated page embeds fake sample data: two ordinary
// credentials plus one with a deliberately hostile site name.
const pageFile = path.join(__dirname, '..', 'output', 'password-page.html');

test.skip(!existsSync(pageFile), 'Generate output/password-page.html first — see tools/playwright/README.md');

const html = existsSync(pageFile) ? readFileSync(pageFile, 'utf8') : '';

test.beforeEach(async ({ page }) => {
  await page.setContent(html, { waitUntil: 'load' });
});

test('renders one card per credential with site and username visible', async ({ page }) => {
  const cards = page.locator('.card');
  await expect(cards).toHaveCount(3);
  await expect(cards.filter({ hasText: 'bank.example' })).toHaveCount(1);
  await expect(cards.filter({ hasText: 'mail.example' })).toHaveCount(1);
  await expect(page.locator('#summary')).toContainText('3 of 3 credential(s)');
});

test('passwords are masked until revealed and toggle back', async ({ page }) => {
  const card = page.locator('.card').filter({ hasText: 'bank.example' });
  const passwordRow = card.locator('.row').filter({ hasText: 'Password' });

  await expect(passwordRow.locator('.val')).toHaveText('••••••••');
  await expect(passwordRow).not.toContainText('s3cret-bank');

  await passwordRow.getByRole('button', { name: 'reveal' }).click();
  await expect(passwordRow.locator('.val')).toHaveText('s3cret-bank');
  await expect(passwordRow.getByRole('button', { name: 'hide' })).toBeVisible();

  await passwordRow.getByRole('button', { name: 'hide' }).click();
  await expect(passwordRow.locator('.val')).toHaveText('••••••••');
});

test('extra fields stay hidden behind the toggle and are masked too', async ({ page }) => {
  const card = page.locator('.card').filter({ hasText: 'bank.example' });
  await expect(card.locator('.toggle')).toContainText('2 more field(s)');

  await card.locator('.toggle').click();
  const recovery = card.locator('.extras .row').filter({ hasText: 'Recovery code' });
  await expect(recovery.locator('.val')).toHaveText('••••••••');
  await recovery.getByRole('button', { name: 'reveal' }).click();
  await expect(recovery.locator('.val')).toHaveText('RC-42');
});

test('the search box filters by site or username and updates the summary', async ({ page }) => {
  await page.locator('#q').fill('bank');
  await expect(page.locator('.card')).toHaveCount(1);
  await expect(page.locator('#summary')).toContainText('1 of 3 credential(s)');

  await page.locator('#q').fill('alice');
  await expect(page.locator('.card')).toHaveCount(1);

  await page.locator('#q').fill('');
  await expect(page.locator('.card')).toHaveCount(3);
});

test('every rendered value row has a copy button', async ({ page }) => {
  const bankCard = page.locator('.card').filter({ hasText: 'bank.example' });
  // Username + password rows render immediately; the two extra rows render too.
  await expect(bankCard.getByRole('button', { name: 'copy' })).toHaveCount(4);
});

test('a hostile site name renders as text and never executes', async ({ page }) => {
  // The hostile site name is plain text inside its card, not injected markup.
  const hostile = page.locator('.card').filter({ hasText: 'mallory' });
  await expect(hostile.locator('.site')).toHaveText('<img src=x onerror=window.__pwned=1>');
  await expect(hostile.locator('img')).toHaveCount(0);

  // The injected onerror handler never ran.
  const pwned = await page.evaluate(() => (window as unknown as { __pwned?: boolean }).__pwned);
  expect(pwned).toBeUndefined();
});
